const request = $json.body ?? $json;
const query = request.query ?? request.state ?? request.property ?? request.componentName ?? '';
if (!request.componentName && !request.query && !request.property && !request.state) throw new Error('Provide componentName, query, property, or state.');
return [{ json: { ...request, query: String(query), repository: 'ElishaSamPeterPrabhu/modus-wc-2.0' } }];

const request = $('Normalize Context Query').item.json;
const response = $json;
const encoded = response.content || '';
const manifestText = Buffer.from(encoded.replace(/\n/g, ''), 'base64').toString('utf8');
const manifest = JSON.parse(manifestText);
const normalize = (value) => String(value ?? '').toLowerCase().replace(/[-_]/g, '');
const query = normalize(request.query);
const exactProperty = request.property ? normalize(request.property) : null;
const componentName = request.componentName;
const modules = manifest.modules || [];
const matches = [];
const candidates = [];
for (const [moduleIndex, module] of modules.entries()) {
  for (const [declarationIndex, declaration] of (module.declarations || []).entries()) {
    const tag = declaration.tagName || declaration.tag;
    if (!tag) continue;
    if (componentName && tag !== componentName && !request.includeSiblings) continue;
    candidates.push({ tag, declaration, source: `src/custom-elements.json#/modules/${moduleIndex}/declarations/${declarationIndex}` });
  }
}
for (const candidate of candidates) {
  const declaration = candidate.declaration;
  const members = [...(declaration.members || []), ...(declaration.attributes || [])];
  const properties = members.filter((member) => {
    const name = normalize(member.name);
    if (exactProperty && name !== exactProperty) return false;
    return !query || [member.name, member.type?.text, member.description].some((value) => normalize(value).includes(query));
  });
  const events = (declaration.events || []).filter((event) => !query || [event.name, event.detail, event.description].some((value) => normalize(value).includes(query)));
  const slots = (declaration.slots || []).filter((slot) => !query || [slot.name, slot.description].some((value) => normalize(value).includes(query)));
  if (properties.length || events.length || slots.length) {
    matches.push({ tag: candidate.tag, supported: true, properties, events, slots, source: candidate.source });
  }
}
return [{ json: { ok: true, repository: request.repository, source: { manifest: 'src/custom-elements.json', commit: response.sha || null }, matches, notFound: matches.length ? [] : [componentName || request.query], warning: null } }];
